export const loanCohort={year:'2026–27',undergraduate:6.52,graduate:8.07,plus:9.07,sourceURL:'https://www.govinfo.gov/content/pkg/FR-2026-09-10/pdf/FR-2026-09-10.pdf'};
export function federalTax(taxable){const brackets=[[12400,.1],[50400,.12],[105700,.22],[201775,.24],[256225,.32],[640600,.35],[Infinity,.37]];let federal=0,last=0;for(const [end,rate]of brackets){federal+=Math.max(0,Math.min(taxable,end)-last)*rate;if(taxable<=end)break;last=end;}return federal;}
export function independentTaxes(profit,retirementPercent=0){const netSE=Math.max(0,profit)*.9235,ordinarySE=netSE>=400?.124*Math.min(netSE,184500)+.029*netSE:0,additionalMedicare=.009*Math.max(0,netSE-200000),retirement=Math.max(0,profit)*retirementPercent/100,federal=federalTax(Math.max(0,profit-ordinarySE/2-16100));return {federal,social:netSE>=400?Math.min(netSE,184500)*.124:0,medicare:(netSE>=400?netSE*.029:0)+additionalMedicare,ordinarySE,additionalMedicare,netSE,retirement,monthly:(profit-retirement-federal-ordinarySE-additionalMedicare)/12,mode:'independent'};}
export function fundingScenario(raw={}){const fields=['cost','grants','cash','studyEarnings','parentFunding','borrowing','interest','years','studyYears'];const n={};for(const k of fields){const value=Number(raw[k]??(k==='years'?10:k==='interest'?6.52:0));if(!Number.isFinite(value)||value<0||value>1e8)return {status:'invalid'};n[k]=value;}if(n.years<1||n.years>40||n.interest>100||n.studyYears>15)return {status:'invalid'};const netPrice=Math.max(0,n.cost-n.grants),need=Math.max(0,netPrice-n.cash-n.studyEarnings-n.parentFunding),principal=n.borrowing,months=n.years*12,r=n.interest/1200,payment=principal===0?0:r===0?principal/months:principal*r/-Math.expm1(-months*Math.log1p(r));const accruedInterest=principal*n.interest/100*n.studyYears/2;return {status:'scenario',...n,netPrice,need,principal,payment,unfunded:Math.max(0,need-principal),excessFunding:Math.max(0,n.cash+n.studyEarnings+n.parentFunding+principal-netPrice),accruedInterest,repaymentPrincipal:principal+accruedInterest,paymentWithStudyInterest:principal+accruedInterest===0?0:r===0?(principal+accruedInterest)/months:(principal+accruedInterest)*r/-Math.expm1(-months*Math.log1p(r))};}
export const freshCareerScenario=()=>({weeklyHours:'40',paidWeeks:'52',workMode:'employee',businessExpenses:'0',cost:'',grants:'0',cash:'0',studyEarnings:'0',parentFunding:'0',borrowing:'0',interest:'6.52',years:'10',studyYears:'0',debtLinked:false});
export function cleanCareerScenario(raw){const r=freshCareerScenario();if(!raw||typeof raw!=='object')return r;for(const key of Object.keys(r)){if(key==='debtLinked')r[key]=raw[key]===true;else if(key==='workMode')r[key]=raw[key]==='independent'?'independent':'employee';else if(typeof raw[key]==='string'||typeof raw[key]==='number'){const n=Number(raw[key]);if(Number.isFinite(n)&&n>=0&&n<=1e8)r[key]=String(raw[key]).slice(0,30);}}return r;}
